import{describe,it,expect}from"vitest";import{AWARD_ENCYCLOPEDIA,getAwardDetailsByKey,searchAwardsAndRecipients,filterAwardsByCategory}from"../../frontend/js-modules/national-awards.js";describe("President's Police Medal Explorer Dataset",()=>{it("contains the 'presidents-police-medal' dataset entry",()=>{const e=AWARD_ENCYCLOPEDIA["presidents-police-medal"];expect(e).toBeDefined(),expect(e.id).toBe("presidents-police-medal"),expect(e.name).toContain("President's Police Medal"),expect(e.category).toBe("gallantry"),expect(e.establishedYear).toBe("1951")}),it("contains all required dataset sections (Eligibility, History, Medal Design, Winners, Facts)",()=>{const e=getAwardDetailsByKey("presidents-police-medal");expect(e).not.toBeNull(),expect(e.eligibility).toBeTruthy(),expect(e.history).toBeTruthy(),expect(e.medalDesign).toBeTruthy(),expect(Array.isArray(e.notableWinners)).toBe(!0),expect(e.notableWinners.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.interestingFacts)).toBe(!0),expect(e.interestingFacts.length).toBeGreaterThanOrEqual(3)}),it("includes notable police leaders and hero recipients in dataset",()=>{const e=getAwardDetailsByKey("presidents-police-medal").notableWinners.map(e=>e.name);expect(e.some(e=>e.includes("Ajit Doval"))).toBe(!0),expect(e.some(e=>e.includes("K. P. S. Gill"))).toBe(!0),expect(e.some(e=>e.includes("Hemant Karkare"))).toBe(!0),expect(e.some(e=>e.includes("Tukaram Omble"))).toBe(!0),expect(e.some(e=>e.includes("Kiran Bedi"))).toBe(!0)}),it("searches and filters President's Police Medal accurately",()=>{const e=searchAwardsAndRecipients("President's Police Medal");expect(e.length).toBeGreaterThanOrEqual(1),expect(e.some(e=>"presidents-police-medal"===e.id)).toBe(!0);const t=searchAwardsAndRecipients("Tukaram Omble");expect(t.length).toBeGreaterThanOrEqual(1),expect(t[0].id).toBe("presidents-police-medal");const a=filterAwardsByCategory("gallantry");expect(a.some(e=>"presidents-police-medal"===e.id)).toBe(!0)})});